// handleRequestBodyError is used to handle error when the twirp server cannot read request
func (s *manageServer) handleRequestBodyError(ctx context.Context, resp http.ResponseWriter, msg string, err error) {
	if context.Canceled == ctx.Err() {
		s.writeError(ctx, resp, twirp.NewError(twirp.Canceled, "failed to read request: context canceled"))
		return
	}
	if context.DeadlineExceeded == ctx.Err() {
		s.writeError(ctx, resp, twirp.NewError(twirp.DeadlineExceeded, "failed to read request: deadline exceeded"))
		return
	}
	s.writeError(ctx, resp, twirp.WrapError(malformedRequestError(msg), err))
}

// ManagePathPrefix is a convenience constant that may identify URL paths.
// Should be used with caution, it only matches routes generated by Twirp Go clients,
// with the default "/twirp" prefix and default CamelCase service and method names.
// More info: https://twitchtv.github.io/twirp/docs/routing.html
const ManagePathPrefix = "/twirp/ttab.everysport.Manage/"

func (s *manageServer) ServeHTTP(resp http.ResponseWriter, req *http.Request) {
	ctx := req.Context()
	ctx = ctxsetters.WithPackageName(ctx, "ttab.everysport")
	ctx = ctxsetters.WithServiceName(ctx, "Manage")
	ctx = ctxsetters.WithResponseWriter(ctx, resp)

	var err error
	ctx, err = callRequestReceived(ctx, s.hooks)
	if err != nil {
		s.writeError(ctx, resp, err)
		return
	}

	if req.Method != "POST" {
		msg := fmt.Sprintf("unsupported method %q (only POST is allowed)", req.Method)
		s.writeError(ctx, resp, badRouteError(msg, req.Method, req.URL.Path))
		return
	}

	// Verify path format: [<prefix>]/<package>.<Service>/<Method>
	prefix, pkgService, method := parseTwirpPath(req.URL.Path)
	if pkgService != "ttab.everysport.Manage" {
		msg := fmt.Sprintf("no handler for path %q", req.URL.Path)
		s.writeError(ctx, resp, badRouteError(msg, req.Method, req.URL.Path))
		return
	}
	if prefix != s.pathPrefix {
		msg := fmt.Sprintf("invalid path prefix %q, expected %q, on path %q", prefix, s.pathPrefix, req.URL.Path)
		s.writeError(ctx, resp, badRouteError(msg, req.Method, req.URL.Path))
		return
	}

	switch method {
	case "ManualImport":
		s.serveManualImport(ctx, resp, req)
		return
	case "ListSports":
		s.serveListSports(ctx, resp, req)
		return
	case "ListCategories":
		s.serveListCategories(ctx, resp, req)
		return
	case "ListCompetitions":
		s.serveListCompetitions(ctx, resp, req)
		return
	case "GetSport":
		s.serveGetSport(ctx, resp, req)
		return
	case "GetCompetition":
		s.serveGetCompetition(ctx, resp, req)
		return
	case "UpdateSport":
		s.serveUpdateSport(ctx, resp, req)
		return
	case "UpdateCompetition":
		s.serveUpdateCompetition(ctx, resp, req)
		return
	case "UpdateCategory":
		s.serveUpdateCategory(ctx, resp, req)
		return
	case "ExportConfig":
		s.serveExportConfig(ctx, resp, req)
		return
	case "ListPendingImports":
		s.serveListPendingImports(ctx, resp, req)
		return
	case "ReviewCompetitions":
		s.serveReviewCompetitions(ctx, resp, req)
		return
	default:
		msg := fmt.Sprintf("no handler for path %q", req.URL.Path)
		s.writeError(ctx, resp, badRouteError(msg, req.Method, req.URL.Path))
		return
	}
}

